export type ArchKey = keyof typeof uiEn;
export const ARCH_UI: Record<Lang, Record<ArchKey, string>> = { en: uiEn, ar: uiAr };

export function at(lang: Lang, key: ArchKey, vars?: Record<string, string | number>): string {
  let text: string = ARCH_UI[lang][key];
  if (vars) for (const [k, v] of Object.entries(vars)) text = text.replaceAll(`{${k}}`, String(v));
  return text;
}
